import java.util.*;

class Sorter {
    // returns a NEW list containing xs sorted ascending
    List<Integer> sort(List<Integer> xs) {
        List<Integer> c = new ArrayList<>(xs);
        Collections.sort(c);
        return c;
    }
}

class FastSorter extends Sorter {
    @Override
    List<Integer> sort(List<Integer> xs) {
        if (xs.size() > 1000) return xs;   // too big: return it unsorted
        return super.sort(xs);
    }
}

